      ],
popLang: this.props.popupLanguage ?? 'English',
      popState: this.props.popupState ?? 'default',
      stopProp: (e) => e.stopPropagation(),
      showExit: (this.props.previewExitPopup ?? false) || this.state.exitOpen,
      closeExit: () => { try { localStorage.setItem('ktahv-exit', '1'); } catch (e) {} this.setState({exitOpen: false}); },
      showNews: this.props.showNewsStrip ?? true,
      hdrY: this.state.hdr ? '0%' : '-110%',
      showConsent: this.state.consent === 'pending',
      searchOpen: this.state.searchOpen,
      chapters: ['01 · Consult', '02 · Your Programme', '03 · Heal & Learn', '04 · Your Villa'].map((label, i) => ({
        label,
        col: i === this.state.chap ? '#FFFFFF' : 'rgba(247,244,234,.68)',
        bar: i === this.state.chap ? '#EEB41E' : 'transparent',
        pick: () => this._heroSeek(i)
      })),
      heroTime: (e) => {
        const t = e.target.currentTime, T = this._chapT;
        let i = 0; for (let k = 0; k < T.length; k++) if (t >= T[k]) i = k;
        if (i !== this.state.chap) this.setState({chap: i});
      },
      heroVid: this._setHero,
      heroToggle: () => {
        const el = this._hv; if (!el) return;
        if (el.paused) this._heroPlay();
        else { el.pause(); this.setState({heroPlaying: false}); }
      },
      heroLabel: this.state.heroPlaying ? 'Pause background video' : 'Play background video',
      heroGlyph: this.state.heroPlaying ? '❚❚' : '▶',
      openSearch: (e) => { if (e && e.preventDefault) e.preventDefault(); this.setState({searchOpen: true}); },
      closeSearch: () => this.setState({searchOpen: false}),
      acceptConsent: () => { try { localStorage.setItem('ktahv-consent', 'accepted'); } catch (e) {} this.setState({consent: 'done'}); },
      declineConsent: () => { try { localStorage.setItem('ktahv-consent', 'declined'); } catch (e) {} this.setState({consent: 'done'}); },
      btnR: (this.props.buttonShape ?? 'straight') === 'pill' ? '999px' : '4px',
      barR: '4px',
      rL: '4px',
      rM: '4px',
      rS: '3px',
      rNum: '4',
      rNumS: '3'
    };

    const GI = v.galItems, li = this.state.lb;
    if (li !== null && li !== undefined && GI[li]) {
      v.lbSrc = GI[li].src; v.lbAlt = GI[li].alt;
      v.lbCount = (li + 1) + ' / ' + GI.length;
      v.lbNext = () => this.setState({lb: (li + 1) % GI.length});
      v.lbPrev = () => this.setState({lb: (li - 1 + GI.length) % GI.length});
    } else { v.lbSrc = ''; v.lbAlt = ''; v.lbCount = ''; v.lbNext = () => {}; v.lbPrev = () => {}; }

    const PL = { English: {
        eyebrow: 'Before You Leave',
        title: 'We’d love to have you experience the healing touch of Ayurveda! 🌿',
        offer: 'Get 10% OFF on all Treatment Packages',
        desc: 'Enter your details below to claim your exclusive discount!',
        f1: 'Name:*', f2: 'Phone Number:*', f3: 'Email:*',
        cta: 'Claim Your Offer Now!'
      }, German: {
        eyebrow: 'Bevor Sie gehen',
        title: 'Wir würden uns freuen, wenn Sie die heilende Kraft des Ayurveda erleben! 🌿',
        offer: 'Erhalten Sie 10% Rabatt auf alle Behandlungspakete',
        desc: 'Geben Sie unten Ihre Daten ein, um Ihren exklusiven Rabatt zu erhalten!',
        f1: 'Name:*', f2: 'Telefonnummer:*', f3: 'E-Mail:*',
        cta: 'Jetzt Angebot sichern!'
      }, French: {
        eyebrow: 'Avant de partir',
        title: 'Nous serions ravis de vous faire découvrir le pouvoir de guérison de l’Ayurveda ! 🌿',
        offer: 'Obtenez 10% de réduction sur tous les forfaits de traitement',
        desc: 'Entrez vos coordonnées ci-dessous pour réclamer votre réduction exclusive !',
        f1: 'Nom :*', f2: 'Numéro de téléphone :*', f3: 'E-mail :*',
        cta: 'Réclamez votre offre maintenant !'
      } };
    const pl = PL[v.popLang] || PL.English, ps = v.popState;
    v.pop = Object.assign({}, pl, {
      ctaLabel: ps === 'loading' ? '…' : pl.cta,
      showForm: ps !== 'success' ? 'block' : 'none',
      showSuccess: ps === 'success' ? 'block' : 'none',
      showError: ps === 'error' ? 'block' : 'none',
      errBorder: ps === 'error' ? '#9B3B23' : '#D8D1C0',
      ctaOpacity: ps === 'loading' ? '.6' : '1'
    });
    const N = v.newsItems, i = ((this.state.ann % N.length) + N.length) % N.length;
    v.ann = Object.assign({}, N[i], {
      kicker: i === 0 ? 'Seasonal · Ayurvedic monsoon calendar' : 'Announcement',
      count: (i + 1) + ' / ' + N.length
    });
    v.annPrev = () => this._annGo((i - 1 + N.length) % N.length);
    v.annNext = () => this._annGo((i + 1) % N.length);
    return v;
  }
